export function UserRow({
  name,
  status = "online",
  avatarUrl,
  initials,
}: {
  name: string;
  status?: "online" | "offline" | "away";
  avatarUrl?: string;
  initials?: string;
}) {
  const statusDot =
    status === "online"
      ? "bg-zinc-100"
      : status === "away"
        ? "bg-zinc-400"
        : "bg-zinc-500";

  return (
    <div className="flex items-center gap-3 p-3 rounded-lg border border-zinc-800 bg-zinc-900">
      <div className="h-9 w-9 shrink-0 rounded-full bg-zinc-800 text-zinc-300 text-sm font-medium flex items-center justify-center overflow-hidden">
        {avatarUrl ? (
          <img
            src={avatarUrl}
            alt=""
            className="h-full w-full object-cover"
          />
        ) : (
          initials ?? name.slice(0, 1).toUpperCase()
        )}
      </div>

      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-medium text-zinc-100">
          {name}
        </p>
      </div>

      <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-zinc-800 text-xs text-zinc-300">
        <span className={`h-1.5 w-1.5 rounded-full ${statusDot}`} />
        {status}
      </span>
    </div>
  );
}
