    </svg>
  );
}

export function EmptyState({
  icon = <InboxIcon />,
  message,
  hint,
  className = "",
}: EmptyStateProps) {
  return (
    <div
      role="status"
      className={`flex flex-col items-center gap-3 p-6 rounded-lg border border-zinc-800 bg-zinc-900 text-center ${className}`}
    >
      <div className="flex h-10 w-10 items-center justify-center rounded-full bg-zinc-800 text-zinc-300">
        {icon}
